package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"

	"github.com/aws/aws-lambda-go/events"
	"github.com/aws/aws-lambda-go/lambda"
	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

type SearchRequest struct {
	Query    string `json:"query"`
	Category string `json:"category"`
	Limit    int    `json:"limit"`
}

type Product struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Price    float64 `json:"price"`
	Category string `json:"category"`
}

// sanitizeInput performs basic input validation
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	return input
}

// buildSearchQuery constructs the SQL query for product search
func buildSearchQuery(req SearchRequest) string {
	baseQuery := "SELECT id, name, price, category FROM products WHERE 1=1"

	if req.Query != "" {
		// Using ILIKE for case-insensitive search
		baseQuery += fmt.Sprintf(" AND name ILIKE '%%%s%%'", sanitizeInput(req.Query))
	}

	if req.Category != "" {
		baseQuery += fmt.Sprintf(" AND category = '%s'", sanitizeInput(req.Category))
	}

	limit := req.Limit
	if limit <= 0 || limit > 100 {
		limit = 20
	}
	baseQuery += fmt.Sprintf(" LIMIT %d", limit)

	return baseQuery
}

func handleRequest(ctx context.Context, event events.LambdaFunctionURLRequest) (events.LambdaFunctionURLResponse, error) {
	// Only accept POST requests
	if event.RequestContext.HTTP.Method != http.MethodPost {
		return events.LambdaFunctionURLResponse{
			StatusCode: 405,
			Body:       `{"error": "method not allowed"}`,
		}, nil
	}

	var req SearchRequest
	if err := json.Unmarshal([]byte(event.Body), &req); err != nil {
		return events.LambdaFunctionURLResponse{
			StatusCode: 400,
			Body:       `{"error": "invalid request body"}`,
		}, nil
	}

	query := buildSearchQuery(req)
	rows, err := db.QueryContext(ctx, query)
	if err != nil {
		return events.LambdaFunctionURLResponse{
			StatusCode: 500,
			Body:       fmt.Sprintf(`{"error": "query failed: %s"}`, err.Error()),
		}, nil
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	respBody, _ := json.Marshal(map[string]interface{}{
		"results": products,
		"count":   len(products),
	})

	return events.LambdaFunctionURLResponse{
		StatusCode: 200,
		Headers:    map[string]string{"Content-Type": "application/json"},
		Body:       string(respBody),
	}, nil
}

func main() {
	lambda.Start(handleRequest)
}
